class AnalyticsTracker{constructor(){this.sessionId=this.getOrCreateSessionId(),this.pageLoadTime=Date.now(),this.init()}init(){this.trackPageView(),this.trackClicks(),this.trackFormSubmissions(),this.trackScroll(),this.trackHeatmap(),this.initABTests()}getOrCreateSessionId(){let t=sessionStorage.getItem("analytics_session_id");return t||(t="session_"+Date.now()+"_"+Math.random().toString(36).substr(2,9),sessionStorage.setItem("analytics_session_id",t)),t}trackPageView(){const t={event_type:"page_view",event_name:"Page View",page_url:window.location.href,page_title:document.title,metadata:{referrer:document.referrer,load_time:Date.now()-this.pageLoadTime,viewport_width:window.innerWidth,viewport_height:window.innerHeight}};this.sendEvent(t)}trackClicks(){document.addEventListener("click",t=>{const e=t.target.closest('a, button, [role="button"], input[type="submit"]');if(e){const t={event_type:"click",event_name:"Click",page_url:window.location.href,page_title:document.title,element_id:e.id||null,element_class:e.className||null,element_text:e.textContent?.trim().substring(0,100)||null,metadata:{tag_name:e.tagName,href:e.href||null}};this.sendEvent(t)}},!0)}trackFormSubmissions(){document.addEventListener("submit",t=>{const e=t.target,n={event_type:"form_submit",event_name:"Form Submit",page_url:window.location.href,page_title:document.title,element_id:e.id||null,element_class:e.className||null,metadata:{form_action:e.action||null,form_method:e.method||null}};this.sendEvent(n)})}trackScroll(){const t=[25,50,75,100],e=new Set;window.addEventListener("scroll",()=>{const n=Math.round(window.scrollY/(document.documentElement.scrollHeight-window.innerHeight)*100);for(const a of t)n>=a&&!e.has(a)&&(e.add(a),this.sendHeatmap({page_url:window.location.href,page_title:document.title,interaction_type:"scroll",scroll_depth:a}))},{passive:!0})}trackHeatmap(){document.addEventListener("click",t=>{const e={page_url:window.location.href,page_title:document.title,x_position:Math.round(t.clientX),y_position:Math.round(t.clientY),viewport_width:window.innerWidth,viewport_height:window.innerHeight,element_selector:this.getElementSelector(t.target),element_type:t.target.tagName.toLowerCase(),interaction_type:"click",scroll_depth:Math.round(window.scrollY/(document.documentElement.scrollHeight-window.innerHeight)*100)};this.sendHeatmap(e)},!0)}getElementSelector(t){if(t.id)return"#"+t.id;let e=t.tagName.toLowerCase();return t.className&&(e+="."+t.className.split(" ").join(".")),e}async initABTests(){const t=window.location.pathname;try{const e=await fetch(`/api/analytics/ab-tests?url=${encodeURIComponent(t)}`,{headers:{"X-Requested-With":"XMLHttpRequest",Accept:"application/json"}});if(e.ok){const t=await e.json();for(const e of t)await this.assignABTestVariant(e.id)}}catch(t){}}async assignABTestVariant(t){try{const e=await fetch(`/api/analytics/ab-test/${t}`,{headers:{"X-Requested-With":"XMLHttpRequest",Accept:"application/json"}});if(e.ok){const n=await e.json();this.applyABTestVariant(t,n.variant)}}catch(t){}}applyABTestVariant(t,e){sessionStorage.setItem(`ab_test_${t}`,e),window.dispatchEvent(new CustomEvent("ab-test-assigned",{detail:{testId:t,variant:e}}))}async markABTestConversion(t){try{await fetch("/api/analytics/ab-test/conversion",{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest",Accept:"application/json","X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]')?.content||""},body:JSON.stringify({test_id:t})})}catch(t){}}async trackFunnelStep(t,e,n=!1){try{await fetch("/api/analytics/funnel",{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest",Accept:"application/json","X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]')?.content||""},body:JSON.stringify({funnel_id:t,step_number:e,completed:n})})}catch(t){}}async sendEvent(t){try{await fetch("/api/analytics/track",{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest",Accept:"application/json","X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]')?.content||""},body:JSON.stringify(t)})}catch(t){}}async sendHeatmap(t){try{await fetch("/api/analytics/heatmap",{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest",Accept:"application/json","X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]')?.content||""},body:JSON.stringify(t)})}catch(t){}}}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>{window.analyticsTracker=new AnalyticsTracker}):window.analyticsTracker=new AnalyticsTracker;